#define MAX_STATIONS 100
#define MAX_TICKETS 100
#define MAX_LINE 1000

// Graph structure for railway network
int adj[MAX_STATIONS][MAX_STATIONS];
int num_stations;
char station_names[MAX_STATIONS][50];
int station_count;

// Ticket structure
typedef struct {
    int boarding;
    int destination;
    int max_stops;
} Ticket;

Ticket tickets[MAX_TICKETS];
int num_tickets;

// Function to find station index by name
int find_station(char *name) {
    for (int i = 0; i < station_count; i++) {
        if (strcmp(station_names[i], name) == 0) {
            return i;
        }
    }
    return -1;
}

// Function to add a station
int add_station(char *name) {
    int idx = find_station(name);
    if (idx == -1) {
        strcpy(station_names[station_count], name);
        idx = station_count;
        station_count++;
    }
    return idx;
}

// BFS to find shortest path length (number of edges)
int bfs_shortest_path(int start, int end) {
    if (start == end) return 0;

    int visited[MAX_STATIONS] = {0};
    int queue[MAX_STATIONS];
    int dist[MAX_STATIONS];
    int front = 0, rear = 0;

    for (int i = 0; i < station_count; i++) {
        dist[i] = -1;
    }

    queue[rear++] = start;
    visited[start] = 1;
    dist[start] = 0;

    while (front < rear) {
        int current = queue[front++];

        for (int i = 0; i < station_count; i++) {
            if (adj[current][i] && !visited[i]) {
                visited[i] = 1;
                dist[i] = dist[current] + 1;
                queue[rear++] = i;

                if (i == end) {
                    return dist[i];
                }
            }
        }
    }

    return -1; // No path found
}

int main() {
    char line[MAX_LINE];
    char station1[50], station2[50];
