        }
    }

    // Read connections
    for (int i = 0; i < m; i++) {
        fgets(line, MAX_LINE, stdin);
        line[strcspn(line, "\n")] = 0;

        // Parse the connection line
        char *token = strtok(line, " ");
        if (token != NULL) {
            strcpy(station1, token);
            token = strtok(NULL, " ");
            if (token != NULL) {
                strcpy(station2, token);

                int s1 = find_station(station1);
                int s2 = find_station(station2);

                if (s1 != -1 && s2 != -1) {
                    adj[s1][s2] = 1;
                    adj[s2][s1] = 1; // Undirected graph
                }
            }
        }
    }

    // Read number of tickets
    scanf("%d", &k);
    getchar();

    // Read tickets
    for (int i = 0; i < k; i++) {
