                        tickets[num_tickets].boarding = boarding;
                        tickets[num_tickets].destination = destination;
                        tickets[num_tickets].max_stops = max_stops;
                        num_tickets++;
                    }
                }
            }
        }
    }

    // Process each ticket
    for (int i = 0; i < num_tickets; i++) {
        int shortest = bfs_shortest_path(tickets[i].boarding, tickets[i].destination);

        if (shortest == -1) {
            // No path exists
            printf("NO\n");
