int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int *dist = (int *)malloc((size_t)n * n * sizeof(int));
    if (!dist) return 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dist[i * n + j] = (i == j ? 0 : INF);
        }
    }

    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        u--; v--;
        if (w < dist[u * n + v]) {
            dist[u * n + v] = w;
            dist[v * n + u] = w;
        }
    }

    /* Floyd-Warshall for all-pairs shortest paths */
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if (dist[i * n + k] == INF) continue;
            for (int j = 0; j < n; j++) {
                if (dist[k * n + j] == INF) continue;
                int nd = dist[i * n + k] + dist[k * n + j];
                if (nd < dist[i * n + j]) dist[i * n + j] = nd;
            }
        }
    }

    int q;
    scanf("%d", &q);

    while (q--) {
        int a, b, s, t;
        scanf("%d %d %d %d", &a, &b, &s, &t);
        a--; b--; s--; t--;

        /*
          Ticket allows travel from a to b, with intermediate stops.
          Journey s -> t is possible iff both s and t lie on some shortest path from a to b
          and s appears before t along that path.

          This can be checked by:
          dist[a][s] + dist[s][t] + dist[t][b] == dist[a][b]
          or in reverse direction:
          dist[b][s] + dist[s][t] + dist[t][a] == dist[a][b]
        */
        int dab = dist[a * n + b];
        int dst = dist[s * n + t];

        int ok = 0;
        if (dab < INF && dst < INF) {
            if (dist[a * n + s] < INF && dist[t * n + b] < INF &&
                dist[a * n + s] + dst + dist[t * n + b] == dab)
                ok = 1;
            if (dist[b * n + s] < INF && dist[t * n + a] < INF &&
                dist[b * n + s] + dst + dist[t * n + a] == dab)
                ok = 1;
        }

        printf(ok ? "Yes\n" : "No\n");
    }

    free(dist);
    return 0;
}

