*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<vector<int>> g(N + 1);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int Q;
    cin >> Q;

    // Cache BFS distances by source to handle repeated sources efficiently.
    unordered_map<int, vector<int>> dist_cache;

    auto get_dist = [&](int src) -> vector<int>& {
        auto it = dist_cache.find(src);
        if (it != dist_cache.end()) return it->second;

        vector<int> dist(N + 1, -1);
        queue<int> qu;
        dist[src] = 0;
        qu.push(src);

        while (!qu.empty()) {
            int u = qu.front();
            qu.pop();
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    qu.push(v);
                }
            }
        }

        auto res = dist_cache.emplace(src, move(dist));
        return res.first->second;
    };

    while (Q--) {
        int S, T, A, B;
        cin >> S >> T >> A >> B;

        auto &dS = get_dist(S);
        auto &dA = get_dist(A);
        auto &dB = get_dist(B);

        bool ok = false;
        if (dS[T] != -1 && dS[A] != -1 && dA[B] != -1 && dB[T] != -1) {
            ok = (dS[A] + dA[B] + dB[T] == dS[T]);
        }

        cout << (ok ? "YES" : "NO") << '\n';
    }

    return 0;
}

