public class TrainJourney {
    static final int INF = 1_000_000_000;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split(" ");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);

            if (n == 0 && m == 0) break;

            // Build adjacency matrix
            int[][] dist = new int[n][n];
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], INF);
                dist[i][i] = 0;
            }

            for (int i = 0; i < m; i++) {
                parts = br.readLine().split(" ");
                int a = Integer.parseInt(parts[0]) - 1;
                int b = Integer.parseInt(parts[1]) - 1;
                int c = Integer.parseInt(parts[2]);
                if (c < dist[a][b]) {
                    dist[a][b] = c;
                    dist[b][a] = c;
                }
            }

            // Floyd-Warshall
            for (int k = 0; k < n; k++) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (dist[i][k] + dist[k][j] < dist[i][j]) {
                            dist[i][j] = dist[i][k] + dist[k][j];
                        }
                    }
                }
            }

            int p = Integer.parseInt(br.readLine());
            for (int t = 0; t < p; t++) {
                parts = br.readLine().split(" ");
                int s = Integer.parseInt(parts[0]) - 1;
                int d = Integer.parseInt(parts[1]) - 1;
                int k = Integer.parseInt(parts[2]);

                // k is the maximum number of intermediate stops allowed
                // We need to find if there's a path with at most k intermediate stops
                // that has the same length as the shortest path

                int shortest = dist[s][d];
                if (shortest == INF) {
                    System.out.println("No");
                    continue;
                }

                // BFS/DFS to check if there's a path with shortest distance
                // and at most k intermediate stops
                boolean found = false;

                // Use BFS with state (node, stops, distance)
                Queue<int[]> queue = new LinkedList<>();
                // visited[node][stops] = min distance to reach node with exactly stops
                int[][] minDist = new int[n][k+1];
                for (int i = 0; i < n; i++) {
                    Arrays.fill(minDist[i], INF);
                }

                queue.offer(new int[]{s, 0, 0}); // node, stops, distance
                minDist[s][0] = 0;

                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    int node = cur[0];
                    int stops = cur[1];
                    int curDist = cur[2];

                    if (node == d && stops <= k && curDist == shortest) {
                        found = true;
                        break;
                    }

                    if (stops >= k) continue;

                    for (int next = 0; next < n; next++) {
                        if (dist[node][next] != INF && next != node) {
                            int newDist = curDist + dist[node][next];
                            int newStops = stops + 1;
                            if (newDist <= shortest && newStops <= k && newDist < minDist[next][newStops]) {
                                minDist[next][newStops] = newDist;
                                queue.offer(new int[]{next, newStops, newDist});
                            }
                        }
                    }
                }

                System.out.println(found ? "Yes" : "No");
            }
        }
    }
}

