/*
The statement provided is incomplete/ambiguous, so this solution implements
the most natural interpretation:

- There are N stations and M direct undirected connections.
- Then Q tickets are given.
- Each ticket specifies:
    boarding station s,
    destination station t,
    journey start a,
    journey end b.
- A journey from a to b is possible with the ticket (s -> t) iff both a and b
  lie on at least one shortest path from s to t, and a appears before b on that
  shortest path direction from s to t.

Equivalent distance conditions:
1) dist(s, a) + dist(a, t) == dist(s, t)   => a lies on a shortest s-t path
2) dist(s, b) + dist(b, t) == dist(s, t)   => b lies on a shortest s-t path
3) dist(s, a) <= dist(s, b)                => a is not after b along s->t

Input format assumed:
N M
M lines: u v
Q
Q lines: s t a b

Output:
For each query, print "YES" or "NO".

If your original problem uses a slightly different exact format, only the input
parsing may need adjustment; the core shortest-path logic remains the same.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();

        List<Integer>[] g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        int q = fs.nextInt();

        // Cache BFS distances by source station used in queries.
        Map<Integer, int[]> distCache = new HashMap<>();

        for (int i = 0; i < q; i++) {
            int s = fs.nextInt();
            int t = fs.nextInt();
            int a = fs.nextInt();
            int b = fs.nextInt();

            int[] ds = distCache.computeIfAbsent(s, key -> bfs(key, g, n));
            int[] dt = distCache.computeIfAbsent(t, key -> bfs(key, g, n));

            int dst = ds[t];

            boolean ok = false;
            if (dst != -1 && ds[a] != -1 && ds[b] != -1 && dt[a] != -1 && dt[b] != -1) {
                boolean aOnShortest = ds[a] + dt[a] == dst;
                boolean bOnShortest = ds[b] + dt[b] == dst;
                boolean inOrder = ds[a] <= ds[b];
                ok = aOnShortest && bOnShortest && inOrder;
            }

            out.append(ok ? "YES" : "NO").append('\n');
        }

        System.out.print(out);
    }

    static int[] bfs(int src, List<Integer>[] g, int n) {
        int[] dist = new int[n + 1];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> dq = new ArrayDeque<>();
        dist[src] = 0;
        dq.add(src);

        while (!dq.isEmpty()) {
            int u = dq.poll();
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    dq.add(v);
                }
            }
        }
        return dist;
    }
}

