            a = int(input_data[idx]); idx += 1
            b = int(input_data[idx]); idx += 1
            tickets.append((a, b))

        Q = int(input_data[idx]); idx += 1
        for _ in range(Q):
            s = int(input_data[idx]); idx += 1
            t = int(input_data[idx]); idx += 1

            # BFS over stations using tickets
            reachable = set([s])
            queue = deque([s])
            while queue:
                cur = queue.popleft()
                for (a, b) in tickets:
                    if a == cur or (a in dist and cur in dist[a] and dist[a][cur] + dist[cur].get(b, float('inf')) == dist[a].get(b, float('inf'))):
                        # Can use this ticket from cur, reach any station on shortest path from cur to b
                        # Actually ticket is from a to b, board at cur if cur is on path
                        for station in range(1, N+1):
                            if station not in reachable:
                                if dist[a].get(cur,float('inf')) + dist[cur].get(station,float('inf')) + dist[station].get(b,float('inf')) == dist[a].get(b,float('inf')):
                                    reachable.add(station)
                                    queue.append(station)

            print("Yes" if t in reachable else "No")

